"buttons-search-toggle-v11": { markup: "<section class=\"sl-component\" data-kind=\"buttons-search-toggle\" data-active=\"false\" aria-label=\"Search reveal\">\n    <button class=\"motion-button\" type=\"button\" data-action aria-label=\"Open search\" aria-expanded=\"false\" aria-controls=\"local-search-panel\">\n      <span class=\"button-surface\" aria-hidden=\"true\"><span class=\"button-icon\"><svg viewBox=\"0 0 24 24\" focusable=\"false\"><circle class=\"search-ring\" cx=\"10\" cy=\"10\" r=\"5.5\"/><path class=\"search-handle\" d=\"m14.2 14.2 5.3 5.3\"/></svg></span><span class=\"button-label\" data-label>Search</span><span class=\"button-chevron\" aria-hidden=\"true\"><svg viewBox=\"0 0 16 16\" focusable=\"false\"><path d=\"m5 6 3 3 3-3\"/></svg></span></span>\n    </button>\n    <div class=\"search-reveal\" id=\"local-search-panel\" data-panel aria-hidden=\"true\">\n      <div class=\"search-content\">\n        <label class=\"visually-hidden\" for=\"local-search-input\">Search sample projects</label>\n        <div class=\"search-field\">\n          <svg class=\"field-icon\" viewBox=\"0 0 20 20\" aria-hidden=\"true\"><circle cx=\"8.5\" cy=\"8.5\" r=\"4.5\"/><path d=\"m12 12 4 4\"/></svg>\n          <input id=\"local-search-input\" type=\"search\" data-search placeholder=\"Search projects\" autocomplete=\"off\" spellcheck=\"false\">\n          <button class=\"clear-search\" type=\"button\" data-clear aria-label=\"Clear search\"><svg viewBox=\"0 0 16 16\" aria-hidden=\"true\"><path d=\"m4 4 8 8M12 4 4 12\"/></svg></button>\n        </div>\n        <ul class=\"search-results\" data-results aria-label=\"Search results\"></ul>\n      </div>\n    </div>\n    <p class=\"component-status\" data-status role=\"status\" aria-live=\"polite\" aria-atomic=\"true\">Search is closed.</p>\n  </section>", css: style116, mount: api146.mount, rootSelector: ".sl-component", demoMount: api146.mountPreview },
