"buttons-view-switch-v11": { markup: "<section class=\"sl-component\" data-kind=\"buttons-view-switch\" data-active=\"false\" aria-label=\"Grid or list view\">\n    <button class=\"motion-button\" type=\"button\" data-action aria-label=\"List view\" aria-pressed=\"false\">\n      <span class=\"button-surface\" aria-hidden=\"true\"><span class=\"button-icon\"><svg viewBox=\"0 0 24 24\" focusable=\"false\"><g class=\"view-grid\"><rect x=\"4\" y=\"4\" width=\"6\" height=\"6\" rx=\"1\"/><rect x=\"14\" y=\"4\" width=\"6\" height=\"6\" rx=\"1\"/><rect x=\"4\" y=\"14\" width=\"6\" height=\"6\" rx=\"1\"/><rect x=\"14\" y=\"14\" width=\"6\" height=\"6\" rx=\"1\"/></g><g class=\"view-list\"><path d=\"M9 6h11M9 12h11M9 18h11\"/><circle cx=\"5\" cy=\"6\" r=\"1\"/><circle cx=\"5\" cy=\"12\" r=\"1\"/><circle cx=\"5\" cy=\"18\" r=\"1\"/></g></svg></span><span class=\"button-label\" data-label>List view</span></span>\n    </button>\n    <p class=\"component-status\" data-status role=\"status\" aria-live=\"polite\" aria-atomic=\"true\">Grid view is active.</p>\n  </section>", css: style120, mount: api150.mount, rootSelector: ".sl-component", demoMount: api150.mountPreview },
